#[cfg(test)] static HIT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
#[cfg(test)] static HIT_NARROW: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
#[cfg(test)] mod targeted {
use super::*;
fn csr(n:usize,e:&[(usize,usize,u32)],rev:bool)->Csr {let mut rows=vec![Vec::new();n]; for &(u,v,w) in e {let (x,y)=if rev {(v,u)} else {(u,v)};rows[x].push((y,w));} let mut first=Vec::new();let mut compact=Vec::new();let mut wide=Vec::new();for row in rows {first.push(compact.len() as u32);for (v,w) in row {compact.push((w.min(2047)<<21)|v as u32);wide.push(w);}}first.push(compact.len() as u32);Csr{first,adj:Vec::new(),compact,wide}}
#[test] fn seek() {let mut state=0x923456789abcdefu64;let mut rnd=||{state^=state<<7;state^=state>>9;state^=state<<8;state};let palette=[0,1,63,64,65,127,128,129,2046,2047,1_000_000_000,1_500_000_000,2_000_000_000,2_100_000_000,2_147_483_647,2_500_000_000,3_000_000_000,3_500_000_000,4_000_000_000,u32::MAX-1,u32::MAX];let mut above=0u64;for iter in 0..2_000_000 {let n=5+(rnd()%16) as usize;let mut edges=Vec::new();let den=4+(rnd()%8);for u in 0..n {for v in 0..n {if rnd()%den==0 {edges.push((u,v,palette[rnd() as usize%palette.len()]));}}}let graphs=[csr(n,&edges,false),csr(n,&edges,true)];let mut search=Search32::new(n);for _ in 0..5 {let s=(rnd()%n as u64) as usize;let t=(rnd()%n as u64) as usize;HIT.store(0,std::sync::atomic::Ordering::Relaxed);HIT_NARROW.store(0,std::sync::atomic::Ordering::Relaxed);let (ans,drop)=search.distance([&graphs[0],&graphs[1]],s as u32,t as u32);if HIT.load(std::sync::atomic::Ordering::Relaxed)>0 {above+=1;} if HIT_NARROW.load(std::sync::atomic::Ordering::Relaxed)>0 {let mut d=vec![vec![NONE;n];n];for i in 0..n {d[i][i]=0;}for &(u,v,w) in &edges {d[u][v]=d[u][v].min(w as u64);}for k in 0..n {for i in 0..n {for j in 0..n {d[i][j]=d[i][j].min(d[i][k].saturating_add(d[k][j]));}}}println!("FOUND iter={iter} n={n} s={s} t={t} result={ans} expected={} dropped={drop} hits={} edges={edges:?}",d[s][t],HIT.load(std::sync::atomic::Ordering::Relaxed));let actual=if ans<u32::MAX as u64 || !drop {ans} else {Search::new(n).distance([&graphs[0],&graphs[1]],s as u32,t as u32)};assert_eq!(actual,d[s][t]);return;}}}println!("NO BELOW-CUTOFF IMPROVEMENT: graphs=2000000 queries=10000000 any_hit_queries={above}");}
}
